class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        if len(text2) > len(text1):
            text1, text2 = text2, text1   # keep the shorter string on the inner dimension
        n = len(text2)
        prev = [0] * (n + 1)
        for ch in text1:
            cur = [0] * (n + 1)
            for j in range(1, n + 1):
                if ch == text2[j - 1]:
                    cur[j] = prev[j - 1] + 1
                else:
                    cur[j] = max(prev[j], cur[j - 1])
            prev = cur
        return prev[n]

